+		if st, ok2 := t.Elem.(types.StructType); ok2 {
+			loop := c.newLoopVar()
+			c.writeln("printf(\"[\");")
+			c.writeln(fmt.Sprintf("for(int %s=0; %s<%s.len; %s++){", loop, loop, argExpr, loop))
